  function line(x1,y1,x2,y2,color,k,width){return '<line'+id(k)+' x1="'+n(x1)+'" y1="'+n(y1)+'" x2="'+n(x2)+'" y2="'+n(y2)+'" stroke="'+(color||ink)+'" stroke-width="'+(width||2.5)+'"/>';}
