  function add(suffix,title,note,defaults,controls,choices,draw){items['835023'+suffix]={kind:'jh3',title:title,note:note,claimIds:['visual'],defaults:defaults,controls:controls||[],choices:choices||[],draw:draw};}
  function gcd(a,b){a=Math.abs(a);b=Math.abs(b);while(b){var r=a%b;a=b;b=r;}return a||1;}
