  function root(a){if(a===0)return '0';var k=Math.floor(Math.sqrt(a));if(k*k===a)return String(k);for(var q=k;q>1;q--)if(a%(q*q)===0)return q+'√'+(a/(q*q));return '√'+a;}
  function signed(v){return v<0?'−'+Math.abs(v):String(v);}
  function axis(min,max,y,x0,x1,k){var b=line(x0,y,x1,y,ink,k),step=(x1-x0)/(max-min);for(var v=min;v<=max;v++)b+=line(x0+(v-min)*step,y-5,x0+(v-min)*step,y+5,gray)+text(x0+(v-min)*step,y+30,signed(v),21);return b;}
