  add('3121100000','一つの項を、それぞれへかける','面積の図ではxを正の長さとして使う。負の値は式で確かめる。割る式では2xが0でないことが必要。',{x:'2',operation:'multiply'},[],choice('x',[-2,-1,1,2,3]).concat(choice('operation',['multiply','divide'],['かける','わる'])),function(s){var x=Number(s.x),mul=s.operation==='multiply',b='',value=mul?2*x*(x+3):3*x+2;if(mul&&x>0){b=blocks(130,60,[x,3],[2*x],['2x²','6x'],'distribution-part',24)+text(300,260,'2x(x+3) = 2x²+6x',27,'distribution-equation');}else b=text(300,110,mul?'2x(x+3) = 2x²+6x':'(6x²+4x)÷2x = 3x+2',27,'distribution-equation')+text(300,180,'x = '+signed(x),26);b+=text(300,315,'式の値：'+signed(value),28,'distribution-value');return figure(b,'分配法則で各項を計算する例','x='+signed(x)+'のとき、式の値は'+signed(value)+'。');});
  add('3121200000','四つの積を、長方形で見る','xは正の長さ。四つの面積を足す。一般の数で式が成り立つ理由は分配法則で確かめる。',{x:2},[['x','xの長さ',1,3,1]],[],function(s){var x=s.x,b=blocks(90,60,[x,2],[x,3],['x²','2x','3x','6'],'expand-part',36)+rect(90,60,36*(x+2),36*(x+3),'none','expand-outline',ink);return figure(b,'長方形をxと2、xと3で四つに分ける','(x+2)(x+3) = x²+5x+6。x='+x+'では'+((x+2)*(x+3))+'。');});
  add('3121210000','二つのabを、残さず数える','a,bは正の長さ。四つに分けた正方形のうち、abの長方形は二つある。',{a:2,b:1},[['a','aの長さ',1,3,1],['b','bの長さ',1,2,1]],[],function(s){var b=blocks(160,65,[s.a,s.b],[s.a,s.b],['a²','ab','ab','b²'],'square-sum-part',40)+rect(160,65,40*(s.a+s.b),40*(s.a+s.b),'none','square-sum-outline',ink);return figure(b,'一辺a+bの正方形の四分割','(a+b)² = a²+2ab+b²。面積は'+((s.a+s.b)*(s.a+s.b))+'。');});
  add('3121220000','二重にひいた部分を、戻す','a=5、0<b<5。右と下の帯をひくと、右下のb²を二回ひいていることを確かめる。',{b:2,step:0},[['b','bの長さ',1,3,1],['step','確かめる段階',0,3,1]],[],function(s){var b=rect(170,65,200,200,paper,'square-difference-full'),w=40*s.b,r=200-w;if(s.step>=1)b+=rect(170,65+r,200,w,sand,'square-difference-bottom')+rect(170+r,65,w,200,pale,'square-difference-right');if(s.step>=2)b+=rect(170+r,65+r,w,w,sand,'square-difference-overlap',orange)+text(170+r+w/2,65+r+w/2+8,'b²',25);if(s.step===3)b+=rect(170,65,r,r,pale,'square-difference-result',orange);b+=text(270,310,'a=5、b='+s.b,26);var rr=['もとの面積：25','二つの帯：5bを二回ひく','重なりb²を、一回戻す','(5−b)² = 25−10b+b²'];return figure(b,'二つの帯が重なる部分を明示した正方形',rr[s.step]+'。',360,rows(rr,s.step,'square-difference-step'));});
  add('3121230000','正方形の差を、二つの積へ','a=5、0<b<5。残る二つの部分を使い、(a+b)(a−b)の長方形と比べる。',{b:2,view:'difference'},[['b','bの長さ',1,3,1]],choice('view',['difference','rectangle'],['正方形の差','長方形']),function(s){var a=5,b=s.b,r=a-b,body='';if(s.view==='difference'){body=rect(180,60,a*30,r*30,pale,'difference-piece-0')+rect(180,60+r*30,r*30,b*30,sand,'difference-piece-1')+rect(180+r*30,60+r*30,b*30,b*30,'none','difference-removed',gray)+text(180+r*30+b*15,60+r*30+b*15+8,'b²',24);}else body=rect(150,80,a*30,r*30,pale,'difference-piece-0')+rect(150+a*30,80,b*30,r*30,sand,'difference-piece-1')+text(150+(a+b)*15,80+r*30+40,'横 a+b、縦 a−b',25);body+=text(300,310,'25−'+b*b+' = '+(25-b*b),28,'difference-result');return figure(body,'正の面積の二つの部分による平方の差','a²−b² = (a+b)(a−b)。選んだ見方：'+(s.view==='difference'?'正方形の差':'長方形')+'。');});
  add('3144000000','共通する因数で、くくる','因数分解は、同じ式を積で表し直すこと。xで割る操作ではないので、x=0も除かない。',{k:'3',step:0},[['step','確かめる段階',0,2,1]],choice('k',[-3,-2,2,3]),function(s){var k=Number(s.k),rr=[signed(k)+'x² '+(k<0?'− ':'+ ')+Math.abs(2*k)+'x',signed(k)+'x・x '+(k<0?'− ':'+ ')+Math.abs(k)+'x・2',signed(k)+'x(x+2)'];var b=text(170,100,signed(k)+'x²',31,'common-term-0')+text(430,100,signed(2*k)+'x',31,'common-term-1')+rect(185,145,230,65,s.step>=1?pale:paper,'common-factor')+text(300,188,'共通因数 '+signed(k)+'x',28)+text(300,275,s.step===2?rr[2]:'各項を積として見る',28,'common-product');return figure(b,'符号を含む二つの項から共通因数を見付ける',rr[s.step],340,rows(rr,s.step,'common-step'));});
  add('3121240000','和と積を、二つとも確かめる','二数の和がxの係数、積が定数項になる。面積図はx=3の正の例。負の因数は式で確かめる。',{example:'plus',step:0},[['step','確かめる段階',0,3,1]],choice('example',['plus','mixed','minus'],['2と3','−2と3','−2と−3']),function(s){var pair={plus:[2,3],mixed:[-2,3],minus:[-2,-3]}[s.example],sum=pair[0]+pair[1],product=pair[0]*pair[1],b='';if(s.example==='plus')b=blocks(190,55,[3,2],[3,3],['x²','2x','3x','6'],'factor-term',32);else b=text(300,100,'二数：'+signed(pair[0])+' と '+signed(pair[1]),29,'factor-term-0')+text(300,170,'負の符号も、計算に含める',25,'factor-term-1');var answer='(x'+(pair[0]<0?'−':'+')+Math.abs(pair[0])+')(x'+(pair[1]<0?'−':'+')+Math.abs(pair[1])+')',rr=['x²'+(sum<0?'−':'+')+Math.abs(sum)+'x'+(product<0?'−':'+')+Math.abs(product),'和：'+signed(pair[0])+' + ('+signed(pair[1])+') = '+signed(sum),'積：'+signed(pair[0])+' × ('+signed(pair[1])+') = '+signed(product),'因数分解：'+answer];b+=text(300,320,rr[s.step],27,['factor-source','factor-sum','factor-product','factor-answer'][s.step]);return figure(b,'二数の和と積を対応させる因数分解',rr[s.step],365,rows(rr,s.step,'factor-step'));});
  add('3122100000','公式の形を見つけて、積へ戻す','平方の形と、平方の差を区別する。展開してもとの式に戻ることも確かめる。',{example:'square-plus',step:0},[['step','確かめる段階',0,2,1]],choice('example',['square-plus','square-minus','difference'],['和の平方','差の平方','平方の差']),function(s){var v={'square-plus':['x²+6x+9','x²+2・x・3+3²','(x+3)²'],'square-minus':['x²−6x+9','x²−2・x・3+3²','(x−3)²'],difference:['x²−9','x²−3²','(x+3)(x−3)']}[s.example];return figure(text(300,80,v[0],31,'identity-source')+text(300,155,'平方の部分：x² と 3²',27,'identity-square-0')+text(300,230,v[s.step],31,'identity-result'),'三つの公式を符号ごとに比べる',v[s.step],300,rows(v,s.step,'identity-step'));});
  add('3122200000','連続する整数を、文字で確かめる','nは整数。(n+1)²−n²を展開すると2n+1。具体的な値と、どの整数でも成り立つ理由を分けて考える。',{n:2},[['n','整数n',-2,3,1]],[],function(s){var q=s.n,a=(q+1)*(q+1),b=q*q;return figure(text(300,70,'(n+1)²−n² = 2n+1',30)+text(175,150,'(n+1)² = '+a,27,'consecutive-first')+text(425,150,'n² = '+b,27,'consecutive-second')+text(300,240,a+'−'+b+' = '+signed(2*q+1),31,'consecutive-difference'),'連続整数の二乗の差を符号付きの式で確かめる','n='+signed(q)+'では差は'+signed(2*q+1)+'。一般には整数nの2倍に1を足した数。',310);});
  add('3111100000','平方根と、根号が表す数を分ける','正の数aの平方根は正と負の二つ。√aはその正の方を表す。0の平方根は0だけ。',{a:'2',focus:'roots'},[],choice('a',[0,2,4,9]).concat(choice('focus',['roots','principal'],['平方根','√aが表す数'])),function(s){var a=Number(s.a),r=Math.sqrt(a),body=axis(-4,4,265,80,520,'root-axis');if(a>0){body+=rect(70,40,45*r,45*r,pale,'root-area')+text(310,105,'面積 '+a,27)+text(310,155,'一辺 '+root(a),27)+dot(300+55*r,265,7,orange,'root-positive')+dot(300-55*r,265,7,s.focus==='roots'?orange:paper,'root-negative');}else body+=dot(300,265,7,orange,'root-zero')+text(300,125,'0を2乗すると0',29);return figure(body,'根号が表す非負の数と平方根を数直線に示す',s.focus==='principal'?'√'+a+' = '+root(a)+'。':a===0?'0の平方根は0。':a+'の平方根は '+root(a)+' と −'+root(a)+'。',330);});
  add('3142000000','表記だけでなく、数そのものを見る','有理数は整数どうしの分数で表せる数。根号があっても√4=2は有理数。近似小数は元の数とは区別する。',{number:'root2'},[],choice('number',['zero','negative','fraction','root4','root2','pi'],['0','−3','1/3','√4','√2','π']),function(s){var data={zero:[0,'0',true],negative:[-3,'−3',true],fraction:[1/3,'1/3',true],root4:[2,'√4=2',true],root2:[Math.sqrt(2),'√2',false],pi:[Math.PI,'π',false]}[s.number];return figure(text(300,55,data[1],34,'number-range-expression')+rect(90,85,180,65,data[2]?pale:paper,'number-range-rational')+text(180,127,'有理数',27)+rect(330,85,180,65,data[2]?paper:pale,'number-range-irrational')+text(420,127,'無理数',27)+axis(-4,4,210,80,520)+dot(300+55*data[0],210,7,orange,'number-range-point'),'数直線の位置と有理数・無理数の区別',data[1]+' は'+(data[2]?'有理数':'無理数')+'。',285);});
  add('3111200000','根号の中と、外を対応させる','正の平方根の計算を確かめる。√(x²)はxの絶対値で、負のxをそのまま答えにしない。',{example:'simplify'},[],choice('example',['simplify','multiply','divide','square-positive','square-negative','zero'],['√12','√3×√12','√12÷√3','√(3²)','√((−3)²)','√0']),function(s){var cases={simplify:['√12','2√3',Math.sqrt(12)],multiply:['√3×√12','6',6],divide:['√12÷√3','2',2],'square-positive':['√(3²)','3',3],'square-negative':['√((−3)²)','3',3],zero:['√0','0',0]},v=cases[s.example];var b=text(300,80,v[0],32,'radical-source')+text(300,150,'= '+v[1],34,'radical-result')+line(100,240,100+60*v[2],240,green,'radical-length',5)+dot(100,240,4,paper)+dot(100+60*v[2],240,4,orange);return figure(b,'根号を含む式と非負の長さの対応',v[0]+' = '+v[1]+'。',310);});

  function graph(){var b='';for(var x=-3;x<=3;x++){var xx=300+65*x;b+=line(xx,54,xx,306,gray)+text(xx,210,signed(x),21);}for(var y=-18;y<=18;y+=6){var yy=180-7*y;b+=line(105,yy,495,yy,gray);if(y!==0)b+=text(282,yy+7,signed(y),21,null,'end');}return b+line(95,180,510,180,ink)+line(300,320,300,44,ink)+text(535,188,'x',25)+text(324,32,'y',25);}
