  function arc(cx,cy,r,start,end,k,color){var span=end-start;if(span<=0)return '';var a=start*Math.PI/180,b=end*Math.PI/180;return path('M'+n(cx+r*Math.cos(a))+' '+n(cy-r*Math.sin(a))+' A'+r+' '+r+' 0 '+(span>180?1:0)+' 0 '+n(cx+r*Math.cos(b))+' '+n(cy-r*Math.sin(b)),color||orange,k);}
