  function right(p,q,r,k){var ux=q[0]-p[0],uy=q[1]-p[1],vx=r[0]-p[0],vy=r[1]-p[1],u=Math.hypot(ux,uy),v=Math.hypot(vx,vy),z=12;ux=ux/u*z;uy=uy/u*z;vx=vx/v*z;vy=vy/v*z;return path('M'+n(p[0]+ux)+' '+n(p[1]+uy)+' L'+n(p[0]+ux+vx)+' '+n(p[1]+uy+vy)+' L'+n(p[0]+vx)+' '+n(p[1]+vy),ink,k);}
