    function status(message,random){var label=container.querySelector('[data-jh3-sample-source]'),live=container.querySelector('[data-jh3-sample-status]');if(label&&random===true)label.textContent='無作為に選んだ標本';if(label&&random===false)label.textContent='決めて選ぶ例';if(live)live.textContent=message;}
